  const exportSettlementsCsv = () => {
    if (settlements.length === 0) return;
    const rows = [
      ['ID Commande', 'Transporteur', 'N° Suivi', 'Montant Collecté (TND)', 'Frais Livraison (TND)', 'Net Vendeur (TND)', 'Statut', 'Référence Rapprochement'],
      ...settlements.map((st) => [
        `#${st.order_id.slice(-8).toUpperCase()}`,
        st.carrier,
        st.tracking_number || '',
        String(st.collected_amount),
        String(st.courier_fee),
        String(st.net_payout),
        st.status,
        st.settlement_reference || '',
      ]),
    ];
    const csvContent = 'data:text/csv;charset=utf-8,\uFEFF' + rows.map((e) => e.map(x => `"${String(x).replace(/"/g, '""')}"`).join(',')).join('

');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const today = new Date().toISOString().slice(0, 10);
    link.setAttribute('href', url);
    link.setAttribute('download', `catalogue-pandamarket-${scope}-${today}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    setSuccess(`Export CSV généré avec succès (${targetList.length} produit(s)).`);
  };

