  // Upload helpers
  const uploadProductFile = async (file: File) => {
    const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
    if (!allowedTypes.includes(file.type)) {
      throw new Error('Veuillez importer une image JPG, PNG ou WebP.');
    }
    if (file.size > 10 * 1024 * 1024) {
      throw new Error("L'image ne doit pas dépasser 10 Mo.");
    }

    const presignRes = await fetchWithCsrf('/api/pd/files/presign', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        filename: file.name,
        content_type: file.type,
        purpose: 'product_image',
      }),
    });

    if (!presignRes.ok) throw new Error(await getErrorMessage(presignRes, "Échec de préparation de l'image"));

    const data = await presignRes.json();
    const uploadUrl = data.upload_url as string | undefined;
    const publicUrl = data.public_url as string | undefined;
    const fileKey = data.file_key as string | undefined;

    if (!uploadUrl || !publicUrl) throw new Error("URL de téléversement manquante");

    const uploadRes = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': file.type },
      body: file,
    });

    if (!uploadRes.ok) throw new Error("Échec de l'envoi de l'image.");

    // Trigger Sharp WebP multi-size variant generation and Cloudflare R2 sync immediately
    if (fileKey) {
      void fetchWithCsrf('/api/pd/files/process-variants', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ file_key: fileKey }),
      }).catch(() => null);
    }

    return publicUrl;
  };

  const handleImageUpload = async (file: File | null) => {
    if (!file) return;
    setError('');
    setSuccess('');
    setUploadingImage(true);
    try {
      const publicUrl = await uploadProductFile(file);
      setForm((current) => ({ ...current, thumbnail: publicUrl }));
      setRawOriginalImage(publicUrl);
      setProcessedStudioImage(publicUrl);
      setStudioSliderPos(50);
      setStudioHistory([]);
      await fetchMediaItems();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Erreur de téléversement d'image");
    } finally {
      setUploadingImage(false);
    }
  };

  const handleGalleryUpload = async (files: FileList | null) => {
    if (!files?.length) return;
    setError('');
    setSuccess('');
    setUploadingImage(true);
    try {
      const urls: string[] = [];
      for (const file of Array.from(files)) {
        urls.push(await uploadProductFile(file));
      }
      setForm((current) => ({
        ...current,
        gallery_images: [...current.gallery_images, ...urls],
      }));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur de téléversement de la galerie');
    } finally {
      setUploadingImage(false);
    }
  };

  const saveProductImage = async (productId: string, thumbnail: string) => {
    if (!thumbnail.trim()) return;
    const res = await fetchWithCsrf(`/api/pd/stores/me/products/${productId}/images`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        url: thumbnail.trim(),
        alt_text: form.title.trim(),
        is_thumbnail: true,
      }),
    });
    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.error?.message || errData.message || "Impossible d'enregistrer l'image principale du produit.");
    }
  };

  const saveGalleryImages = async (productId: string) => {
    const existingUrls = new Set((editingProduct?.images || []).filter((image) => !image.is_thumbnail).map((image) => image.url));
    const newUrls = form.gallery_images.filter((url) => url.trim() && !existingUrls.has(url.trim()));
    for (const url of newUrls) {
      const res = await fetchWithCsrf(`/api/pd/stores/me/products/${productId}/images`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          url: url.trim(),
          alt_text: form.title.trim(),
          is_thumbnail: false,
        }),
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error?.message || errData.message || "Limite d'images par produit atteinte pour votre forfait.");
      }
    }
  };

  const deleteRemovedGalleryImages = async (productId: string) => {
    const keptUrls = new Set(form.gallery_images.map((url) => url.trim()).filter(Boolean));
    const removedImages = (editingProduct?.images || []).filter((image) => !image.is_thumbnail && !keptUrls.has(image.url));
    for (const image of removedImages) {
      await fetchWithCsrf(`/api/pd/stores/me/products/${productId}/images/${image.id}`, {
        method: 'DELETE',
        credentials: 'include',
      });
    }
  };

  // Save product handler
  const handleSave = async () => {
    setError('');
    setSuccess('');
    const price = Number(form.price);
    const inventory = Number(form.inventory_quantity || 0);
    const maxDownloads = Number(form.max_downloads || 5);
    const downloadExpiresHours = Number(form.download_expires_hours || 72);
    const licenseKeys = parseLicenseKeys(form.license_keys);
    const isWholesaleActive = Boolean(form.wholesale_enabled);
    const wholesaleMinQuantity = Number(form.wholesale_min_quantity || 5);
    const wholesalePriceTiers = isWholesaleActive ? parseWholesalePriceTiers(form.wholesale_price_tiers) : [];

    if (isWholesaleActive && wholesalePriceTiers.length === 0) {
      setError("Veuillez renseigner au moins un palier de prix de gros valide ou désactiver l'option B2B.");
      setDrawerTab('pricing');
      return;
    }

    const variants = parseProductVariants(form.variants);

    if (!form.title.trim()) {
      setError('Le titre du produit est obligatoire.');
      setDrawerTab('general');
      return;
    }

    if (!Number.isFinite(price) || price < 0) {
      setError('Le prix doit être un nombre positif valide.');
      setDrawerTab('pricing');
      return;
    }

    const compareAtPrice = form.compare_at_price.trim() ? parseFloat(form.compare_at_price) : null;
    if (compareAtPrice !== null) {
      if (!Number.isFinite(compareAtPrice) || compareAtPrice <= 0) {
        setError("Le prix d'origine (prix barré) doit être un nombre positif.");
        setDrawerTab('pricing');
        return;
      }
      if (compareAtPrice <= price) {
        setError("Le prix d'origine (prix barré) doit être strictement supérieur au prix de vente.");
        setDrawerTab('pricing');
        return;
      }
    }

    for (const v of form.variants) {
      const vPrice = parseFloat(v.price) || 0;
      const vCompare = v.compare_at_price.trim() ? parseFloat(v.compare_at_price) : null;
      if (vCompare !== null) {
        if (!Number.isFinite(vCompare) || vCompare <= 0) {
          setError(`Le prix barré de la variante "${v.title}" doit être un nombre positif.`);
          setDrawerTab('pricing');
          return;
        }
        if (vCompare <= vPrice) {
          setError(`Le prix barré de la variante "${v.title}" (${vCompare} TND) doit être supérieur au prix (${vPrice} TND).`);
          setDrawerTab('pricing');
          return;
        }
      }
    }

    const attributes = form.attributes
      .map((attribute) => ({ name: attribute.name.trim(), value: attribute.value.trim() }))
      .filter((attribute) => attribute.name || attribute.value);

    setCreating(true);
    try {
      let finalStorefrontCategoryId = form.storefront_category_id || null;
      const finalMarketplaceCategoryId = form.marketplace_category_id || null;

      // If storefront_category_id is empty, but an AI candidate was selected, auto-create and link it now!
      if (!finalStorefrontCategoryId && appliedCandidateIndex !== null && aiCategoryCandidates[appliedCandidateIndex]) {
        const candidate = aiCategoryCandidates[appliedCandidateIndex];
        const createdId = await handleApplyCandidate(candidate, appliedCandidateIndex);
        if (createdId) {
          finalStorefrontCategoryId = createdId;
        }
      }

      const isEditing = Boolean(editingProduct);
      const res = await fetchWithCsrf(isEditing ? `/api/pd/stores/me/products/${editingProduct!.id}` : '/api/pd/stores/me/products', {
        method: isEditing ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          type: form.type,
          title: form.title.trim(),
          slug: form.slug.trim(),
          description: form.description.trim() || undefined,
          product_reference: form.product_reference.trim() || null,
          marketplace_category_id: finalMarketplaceCategoryId,
          storefront_category_id: finalStorefrontCategoryId,
          price,
          compare_at_price: compareAtPrice,
          inventory_quantity: Number.isFinite(inventory) && inventory >= 0 ? inventory : 0,
          thumbnail: form.thumbnail.trim() || null,
          seo_title: form.seo_title.trim() || null,
          seo_description: form.seo_description.trim() || null,
          tags: parseTags(form.tags),
          attributes,
          max_downloads: Number.isFinite(maxDownloads) && maxDownloads > 0 ? maxDownloads : 5,
          download_expires_hours: Number.isFinite(downloadExpiresHours) && downloadExpiresHours > 0 ? downloadExpiresHours : 72,
          digital_file_key: form.digital_file_key || null,
          digital_file_name: form.digital_file_name || null,
          digital_file_content_type: form.digital_file_content_type || null,
          digital_file_size: form.digital_file_size ? Number(form.digital_file_size) : null,
          license_keys: form.type === 'serial' ? licenseKeys : undefined,
          wholesale_min_quantity: isWholesaleActive ? (wholesaleMinQuantity >= 2 ? wholesaleMinQuantity : 2) : null,
          wholesale_price_tiers: isWholesaleActive ? wholesalePriceTiers : [],
          metadata: (() => {
            const { wholesale_pricing, ...rest } = editingProduct?.metadata || {} as Record<string, unknown>;
            return {
              ...rest,
              cost_price: form.cost_price ? parseFloat(form.cost_price) : undefined,
            };
          })(),
          variants,
          bundle_pricing_type: form.type === 'bundle' ? form.bundle_pricing_type : undefined,
          bundle_discount_value: form.type === 'bundle' && form.bundle_pricing_type === 'percentage' && form.bundle_discount_value ? parseFloat(form.bundle_discount_value) : undefined,
          bundle_items: form.type === 'bundle' ? form.bundle_items.map((bi, idx) => ({
            product_id: bi.product_id,
            variant_id: bi.variant_id || null,
            quantity: Number(bi.quantity || 1),
            position: idx,
          })) : undefined,
          status: form.status,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        const productId = data.product?.id || editingProduct?.id;
        const thumbnailChanged = form.thumbnail.trim() !== (editingProduct?.thumbnail || '').trim();
        if (productId && form.thumbnail.trim() && (!editingProduct || thumbnailChanged)) {
          await saveProductImage(productId, form.thumbnail);
        }
        if (productId) {
          await deleteRemovedGalleryImages(productId);
          await saveGalleryImages(productId);
        }
        resetForm();
        await fetchProducts();
        setSuccess(isEditing ? 'Produit mis à jour avec succès.' : 'Nouveau produit créé avec succès.');
      } else {
        setError(await getErrorMessage(res, isEditing ? 'Échec de mise à jour' : 'Échec de création'));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur réseau');
    } finally {
      setCreating(false);
    }
  };

  const handleDelete = async (productId: string) => {
    if (!window.confirm('Voulez-vous vraiment supprimer ce produit ?')) return;
    setError('');
    try {
      const res = await fetchWithCsrf(`/api/pd/stores/me/products/${productId}`, {
        method: 'DELETE',
        credentials: 'include',
      });
      if (res.ok) {
        setProducts((current) => current.filter((product) => product.id !== productId));
        setTotalProducts((current) => Math.max(0, current - 1));
        setSuccess('Produit supprimé avec succès.');
      } else {
        setError(await getErrorMessage(res, 'Échec de suppression'));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur réseau');
    }
  };

  const handleStatusChange = async (product: Product, status: string) => {
    setError('');
    try {
      const res = await fetchWithCsrf(`/api/pd/stores/me/products/${product.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ status }),
      });

      if (res.ok) {
        const data = await res.json();
        setProducts((current) => current.map((item) => (item.id === product.id ? { ...item, ...data.product } : item)));
        setSuccess(`Statut mis à jour : ${status}`);
      } else {
        setError(await getErrorMessage(res, 'Impossible de modifier le statut'));
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erreur réseau');
    }
  };

  return (
    <div className="space-y-6">
      {/* 1. CALM STATS & COMMAND BAR */}
      <div className="rounded-2xl border border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900 p-6 shadow-2xs">
        <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
          <div className="flex items-start gap-3.5">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-slate-900 dark:bg-white text-white dark:text-slate-900 shadow-2xs">
              <Package className="h-5 w-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="rounded-md bg-slate-100 dark:bg-slate-800 px-2 py-0.5 text-[10px] font-medium uppercase tracking-wider text-slate-700 dark:text-slate-300">
                  Studio Catalogue Vendeur
                </span>
                <span className="flex items-center gap-1.5 text-xs font-normal text-slate-500 dark:text-slate-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
                  Stock Total : <strong className="text-slate-800 dark:text-slate-200 font-semibold">{totalStockCount}</strong> unités
                </span>
              </div>
              <h1 className="mt-1 text-xl font-semibold tracking-tight text-slate-900 dark:text-white">
                Gestion des Produits & Studio IA
              </h1>
              <p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400 font-normal">
                Gérez votre inventaire, configurez vos déclinaisons SKU et sublimez vos photos studio en 1 clic.
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            {/* View Mode Toggle */}
            <div className="flex items-center rounded-lg border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 p-0.5">
              <button
                type="button"
                onClick={() => setViewMode('table')}
                className={`p-1.5 rounded-md text-xs font-medium transition-colors ${
                  viewMode === 'table'
                    ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-2xs'
                    : 'text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'
                }`}
                title="Vue Tableau Dense"
              >
                <List className="w-3.5 h-3.5" />
              </button>
              <button
                type="button"
                onClick={() => setViewMode('grid')}
                className={`p-1.5 rounded-md text-xs font-medium transition-colors ${
                  viewMode === 'grid'
                    ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-2xs'
                    : 'text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'
                }`}
                title="Vue Grille Studio"
              >
                <LayoutGrid className="w-3.5 h-3.5" />
              </button>
            </div>

            <button
              type="button"
              onClick={() => {
                resetForm();
                setShowDrawer(true);
                handleOpenPromptLibreModal();
              }}
              className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 px-3 py-2 text-xs font-medium text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 transition shadow-2xs"
              title="Créer une fiche produit complète en 15 secondes via un prompt libre ou message WhatsApp"
            >
              <Sparkles className="h-3.5 w-3.5 text-slate-500" />
              <span>Assistant Magique</span>
            </button>

            <button
              type="button"
              onClick={() => {
                resetForm();
                setShowDrawer(true);
              }}
              className="inline-flex items-center gap-1.5 rounded-xl bg-slate-900 dark:bg-white px-3.5 py-2 text-xs font-medium text-white dark:text-slate-900 hover:bg-slate-800 dark:hover:bg-slate-100 transition shadow-2xs"
            >
              <Plus className="h-3.5 w-3.5" />
              <span>Nouveau Produit</span>
            </button>

            <button
              type="button"
              onClick={() => handleExportCSV(selectedIds.size > 0 ? 'selected' : 'filtered')}
              className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 px-3 py-2 text-xs font-medium text-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 transition shadow-2xs"
              title="Exporter le catalogue en fichier CSV pour Excel"
            >
              <Download className="h-3.5 w-3.5 text-slate-400" />
              <span>Export CSV</span>
              {selectedIds.size > 0 && (
                <span className="ml-0.5 px-1.5 py-0.2 rounded-full bg-slate-100 text-slate-800 dark:bg-slate-700 dark:text-slate-200 text-[10px] font-semibold">
                  ({selectedIds.size})
                </span>
              )}
            </button>

            <button
              type="button"
              onClick={() => void fetchProducts()}
              disabled={loading}
              className="inline-flex items-center justify-center p-2 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors disabled:opacity-50 shadow-2xs"
              title="Rafraîchir les données"
            >
              <RefreshCw className={`h-3.5 w-3.5 ${loading ? 'animate-spin text-slate-600' : ''}`} />
            </button>
          </div>
        </div>

        {/* Global Notifications */}
        {error && (
          <div className="mt-4 flex items-center justify-between rounded-xl border border-rose-200/80 bg-rose-50/70 dark:bg-rose-950/30 p-3 text-xs font-medium text-rose-800 dark:text-rose-300 animate-in fade-in">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-4 w-4 shrink-0 text-rose-600" />
              <span>{error}</span>
            </div>
            <button type="button" onClick={() => setError('')} className="p-1 hover:bg-rose-100 rounded-md">
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        )}
        {success && (
          <div className="mt-4 flex items-center justify-between rounded-xl border border-emerald-200/80 bg-emerald-50/70 dark:bg-emerald-950/30 p-3 text-xs font-medium text-emerald-800 dark:text-emerald-300 animate-in fade-in">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600" />
              <span>{success}</span>
            </div>
            <button type="button" onClick={() => setSuccess('')} className="p-1 hover:bg-emerald-100 rounded-md">
              <X className="h-3.5 w-3.5" />
            </button>
          </div>
        )}

        {/* KPI Metric Cards */}
        <div className="mt-5 grid grid-cols-2 sm:grid-cols-4 gap-3 border-t border-slate-100 dark:border-slate-800 pt-4">
          <div
            onClick={() => setStatusFilter('all')}
            className={`p-3.5 rounded-xl border text-xs cursor-pointer transition shadow-2xs ${
              statusFilter === 'all'
                ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-900 border-slate-900'
                : 'bg-slate-50/70 dark:bg-slate-800/40 border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
            }`}
          >
            <span className="text-[10px] font-medium uppercase tracking-wider text-slate-400">Total Références</span>
            <p className="mt-1 text-lg font-semibold">{totalProducts}</p>
          </div>

          <div
            onClick={() => setStatusFilter((curr) => (curr === 'published' ? 'all' : 'published'))}
            className={`p-3.5 rounded-xl border text-xs cursor-pointer transition shadow-2xs ${
              statusFilter === 'published'
                ? 'bg-emerald-50 text-emerald-900 border-emerald-300 ring-1 ring-emerald-300/60 dark:bg-emerald-950/40 dark:text-emerald-200 dark:border-emerald-700'
                : 'bg-slate-50/70 dark:bg-slate-800/40 border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
            }`}
          >
            <span className="text-[10px] font-medium text-emerald-700 dark:text-emerald-400 uppercase tracking-wider">
              Publiés & En Ligne
            </span>
            <p className="mt-1 text-lg font-semibold text-emerald-900 dark:text-emerald-200">{publishedCount}</p>
          </div>

          <div
            onClick={() => setStatusFilter((curr) => (curr === 'draft' ? 'all' : 'draft'))}
            className={`p-3.5 rounded-xl border text-xs cursor-pointer transition shadow-2xs ${
              statusFilter === 'draft'
                ? 'bg-slate-100 text-slate-900 border-slate-300 dark:bg-slate-700 dark:text-white dark:border-slate-600'
                : 'bg-slate-50/70 dark:bg-slate-800/40 border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
            }`}
          >
            <span className="text-[10px] font-medium uppercase tracking-wider text-slate-400">Brouillons</span>
            <p className="mt-1 text-lg font-semibold">{draftCount}</p>
          </div>

          <div
            onClick={() => setStatusFilter((curr) => (curr === 'low_stock' ? 'all' : 'low_stock'))}
            className={`p-3.5 rounded-xl border text-xs cursor-pointer transition shadow-2xs ${
              statusFilter === 'low_stock'
                ? 'bg-amber-50 text-amber-900 border-amber-300 ring-1 ring-amber-300/60 dark:bg-amber-950/40 dark:text-amber-200 dark:border-amber-700'
                : 'bg-slate-50/70 dark:bg-slate-800/40 border-slate-200/80 dark:border-slate-800 hover:border-slate-300'
            }`}
          >
            <span className="text-[10px] font-medium text-amber-700 dark:text-amber-400 uppercase tracking-wider">
              Alertes Stock Faible
            </span>
            <p className="mt-1 text-lg font-semibold text-amber-900 dark:text-amber-200">{lowStockCount}</p>
          </div>
        </div>
      </div>

      {/* 2. CATALOG SEARCH & MODULAR FILTER BAR */}
      <div className="rounded-2xl border border-slate-200/80 dark:border-slate-800 bg-white dark:bg-slate-900 p-3.5 shadow-2xs flex flex-col md:flex-row items-center justify-between gap-3">
        <div className="relative w-full md:w-80">
          <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Rechercher par nom, SKU, catégorie..."
            className="w-full pl-8 pr-8 py-1.5 text-xs rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-900 dark:text-white placeholder:text-slate-400 outline-none transition focus:ring-2 focus:ring-slate-900/10 focus:border-slate-400 shadow-2xs"
          />
          {search && (
            <button
              type="button"
              onClick={() => setSearch('')}
              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-0.5"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>

        <div className="flex flex-wrap items-center gap-2 w-full md:w-auto">
          {/* Status Filter */}
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-3 py-1.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-xs font-normal text-slate-700 dark:text-slate-200 outline-none focus:border-slate-400 shadow-2xs"
          >
            <option value="all">Tous les Statuts</option>
            <option value="published">Publiés</option>
            <option value="draft">Brouillons</option>
